**完整答案**

可按语法做递归下降。# 明确表示空子树；大写字母建立结点；若字母后有括号，就依次分析左子树、逗号、右子树和右括号。

~~~~c
typedef struct BiNode {
    char data;
    struct BiNode *lchild, *rchild;
} BiNode;

static const char *src;
static int pos, ok;

static BiNode *ParseTree(void) {
    if (!ok) return NULL;
    if (src[pos] == '#') {                 /* 空子树 */
        ++pos;
        return NULL;
    }
    if (src[pos] < 'A' || src[pos] > 'Z') {
        ok = 0;
        return NULL;
    }

    BiNode *p = malloc(sizeof *p);
    if (!p) exit(OVERFLOW);
    p->data = src[pos++];
    p->lchild = p->rchild = NULL;

    if (src[pos] == '(') {
        ++pos;
        p->lchild = ParseTree();
        if (src[pos++] != ',') ok = 0;
        p->rchild = ParseTree();
        if (src[pos++] != ')') ok = 0;
    }
    return p;
}

BiNode *CreateTree(const char *s) {
    src = s; pos = 0; ok = 1;
    BiNode *root = ParseTree();
    if (!ok || src[pos] != '\0') {
        DestroyTree(root);
        return NULL;                       /* 语法错误或有多余后缀 */
    }
    return root;
}
~~~~

例如 A(B(#,D),C(E(#,F),#)) 中，B 的左子树由 # 置空，D 为右孩子；C 的右子树也由 # 置空。每个字母、# 和分隔符只读一次，时间 $O(n)$，递归栈 $O(h)$。

**完整答案**

用 onPath 标记“当前递归路径”而不是“全局访问过”，这样回溯后同一顶点仍可出现在另一条简单路径中：

~~~~c
void AllPath(Graph *G, int x, int v, int path[], int depth,
             bool onPath[]) {
    path[depth] = x;
    onPath[x] = true;
    if (x == v) {
        PrintPath(path, depth + 1);
    } else {
        for (Arc *p = G->first[x]; p; p = p->next) {
            int y = p->to;
            if (!onPath[y])
                AllPath(G, y, v, path, depth + 1, onPath);
        }
    }
    onPath[x] = false;
}

/* onPath 全 false 后调用 AllPath(G,u,v,path,0,onPath)。 */
~~~~

题图的弧为 u→a、a→b、u→c、c→d、d→e、d→v、e→u、e→f、e→v、f→b、v→b。按 a、c 及图示邻接顺序展开，搜索过程为：

~~~~text
u
├─ a
│  └─ b                 （死路）
└─ c
   └─ d
      ├─ e
      │  ├─ u            （已在当前路径，跳过）
      │  ├─ f
      │  │  └─ b         （死路）
      │  └─ v            （输出）
      └─ v                （输出）
~~~~

所以全部简单路径恰为

$$\boxed{u\to c\to d\to e\to v},\qquad
\boxed{u\to c\to d\to v}.$$

到达 v 后立即输出并停止向下扩展；每次返回都撤销 onPath[x]。辅助空间 $O(V)$，总时间与搜索树规模及全部输出路径总长度成正比，最坏可为指数级。

**完整答案**

用并查集判断是否成环；孩子-兄弟结点保存 firstChild、nextSibling，并另用 parent 数组便于把一棵已选树重新定根。接受边 (u,v) 时，两端必属不同分量：先把 v 所在树重定根为 v，再把 v 挂成 u 的一个孩子，这样新增的父子边恰好就是原图边 (u,v)。

~~~~c
typedef struct CSNode {
    int v;
    struct CSNode *firstChild, *nextSibling;
} CSNode;

void Detach(CSNode *par, CSNode *child) {
    CSNode **p = &par->firstChild;
    while (*p != child) p = &(*p)->nextSibling;
    *p = child->nextSibling;
    child->nextSibling = NULL;
}

void Reroot(int v, CSNode node[], int parent[]) {
    int child = v, par = parent[child];
    parent[child] = 0;
    while (par != 0) {
        int grand = parent[par];
        Detach(&node[par], &node[child]);
        node[par].nextSibling = node[child].firstChild;
        node[child].firstChild = &node[par];
        parent[par] = child;
        child = par;
        par = grand;
    }
}

Status KruskalCS(EdgeSetType *E, int n, CSNode node[], int parent[]) {
    MakeSet(1, n);                       /* 并查集 */
    for (int i=1;i<=n;i++) {
        node[i]=(CSNode){i,NULL,NULL}; parent[i]=0;
    }
    int chosen=0, u, v;
    while (GetMinEdge(*E,&u,&v)) {
        DelMinEdge(E,u,v);
        if (Find(u)==Find(v)) continue;
        Reroot(v,node,parent);
        node[v].nextSibling=node[u].firstChild;
        node[u].firstChild=&node[v];
        parent[v]=u;
        Union(u,v);
        if (++chosen==n-1) return OK;
    }
    return ERROR;                         /* 不连通，只得到生成森林 */
}
~~~~

Reroot 只反转 v 到原树根路径上的父子方向，不改变所选无向边集合；随后挂接恰增加 (u,v)。并查集保证每次连接两个不同分量，故始终无环；选满 $n-1$ 条时得到 MST。

测试：$G_1$ 无边，返回 ERROR；$G_2$ 依次取 $v_1v_2(10)$、$v_2v_3(20)$，舍弃 $v_3v_1(30)$；$G_3$ 依次取 $v_1v_2(10)$、$v_3v_4(20)$、$v_2v_3(30)$，最终孩子-兄弟树可定根为 $v_1$，形成链 $v_1-v_2-v_3-v_4$。若要优化重定根代价，也可先保存所选边，最后一次 DFS 在 $O(V)$ 内生成孩子-兄弟表示。
